        2: ('L', 2),
        3: ('L', 4),
        6: ('D', 2),
    }
    motifs = []
    # Visit the left stack from top to bottom, then the right stack.
    # Rows of motifs are three rows high with a separator row between them.
    starts = range(0, h, 4)
    for c0 in (0, 4):
        for r0 in starts:
