                      for c in range(c0, min(c0 + 3, w))
                      if grid[r][c] not in (0, 4, 5)}
            if colors:
                motifs.append(next(iter(colors)))

    x, y = marker, 0
    for color in motifs:
        direction, length = stroke[color]
        y += 1  # leave the marker's row as the start of the path
